-- Demo content from the Notion mission shortlist. DEFAULT v1 remains immutable and available to schema-v1 clients.
ALTER TABLE missions DROP CONSTRAINT ck_missions_trigger_type;
ALTER TABLE missions ADD CONSTRAINT ck_missions_trigger_type CHECK (trigger_type IN (
    'TURN_SIGNAL_OFF', 'WIPER_ON', 'LOW_BEAM_ON', 'NAVI_NEXT_TURN', 'NEAR_DESTINATION',
    'NAVI_TRIP_INFO', 'TRIP_STARTED', 'MISSION_CORRECT', 'TRIP_PAUSED', 'DESTINATION_ARRIVED'
));

DO $$
DECLARE
    pack_id BIGINT;
    existing_schema_version INTEGER;
BEGIN
    SELECT schema_version INTO existing_schema_version
    FROM mission_packs WHERE code = 'DEFAULT' AND version = 2;
    IF FOUND THEN
        IF existing_schema_version <> 2 THEN
            RAISE EXCEPTION 'DEFAULT version 2 has schema_version %, expected 2', existing_schema_version;
        END IF;
        RETURN;
    END IF;

    INSERT INTO mission_packs (code, version, schema_version, status)
    VALUES ('DEFAULT', 2, 2, 'DRAFT') RETURNING id INTO pack_id;

    INSERT INTO missions (mission_pack_id, code, trigger_type, config) VALUES
        (pack_id, 'V-01', 'TURN_SIGNAL_OFF', $config$
